const upsertPushToken = `-- name: UpsertPushToken :one
INSERT INTO push_tokens (user_id, device_id, token, platform, environment)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (user_id, token) DO UPDATE SET
    device_id   = COALESCE(EXCLUDED.device_id, push_tokens.device_id),
    platform    = EXCLUDED.platform,
    environment = EXCLUDED.environment,
    updated_at  = now()
RETURNING id, user_id, device_id, token, platform, environment, created_at, updated_at
`

type UpsertPushTokenParams struct {
	UserID      pgtype.UUID `json:"user_id"`
	DeviceID    pgtype.UUID `json:"device_id"`
	Token       string      `json:"token"`
	Platform    string      `json:"platform"`
	Environment string      `json:"environment"`
}

// The key is (user_id, token): the APNs device token IS the identifier, and it
// changes on reinstall. Registering the same token again is an update, not a new
// row — otherwise every app launch would grow the table.
func (q *Queries) UpsertPushToken(ctx context.Context, arg UpsertPushTokenParams) (PushToken, error) {
	row := q.db.QueryRow(ctx, upsertPushToken,
		arg.UserID,
		arg.DeviceID,
		arg.Token,
		arg.Platform,
		arg.Environment,
	)
	var i PushToken
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.DeviceID,
		&i.Token,
		&i.Platform,
		&i.Environment,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

